--

-- Name: rebuild_issuer_closure(uuid); Type: FUNCTION; Schema: orm; Owner: -
--

CREATE FUNCTION orm.rebuild_issuer_closure(p_tenant uuid) RETURNS void
    LANGUAGE plpgsql
    AS $$
BEGIN
    DELETE FROM orm.issuer_hierarchy_closure WHERE tenant_id = p_tenant;
    INSERT INTO orm.issuer_hierarchy_closure
        (ancestor_issuer_id, descendant_issuer_id, hierarchy_type, depth,
         min_ownership_pct, cumulative_ownership_pct, path, tenant_id)
    WITH RECURSIVE tree AS (
        SELECT parent_issuer_id AS anc, child_issuer_id AS desc_, hierarchy_type,
               1 AS depth, ownership_pct AS min_pct, ownership_pct AS cum_pct,
               ARRAY[parent_issuer_id, child_issuer_id] AS path_arr
        FROM orm.issuer_hierarchy
        WHERE tenant_id = p_tenant AND is_current = true
        UNION ALL
        SELECT t.anc, h.child_issuer_id, h.hierarchy_type,
               t.depth + 1,
               LEAST(t.min_pct, h.ownership_pct),
               t.cum_pct * COALESCE(h.ownership_pct, 1) / 100,
               t.path_arr || h.child_issuer_id
        FROM tree t
        JOIN orm.issuer_hierarchy h
          ON h.parent_issuer_id = t.desc_
         AND h.hierarchy_type = t.hierarchy_type
         AND h.tenant_id = p_tenant
         AND h.is_current = true
        WHERE NOT h.child_issuer_id = ANY(t.path_arr)
    )
    SELECT anc, desc_, hierarchy_type, depth,
           min_pct, cum_pct, path_arr::text, p_tenant
    FROM tree;
END;
$$;


--

-- Name: sync_identifier_cache(); Type: FUNCTION; Schema: orm; Owner: -
--

CREATE FUNCTION orm.sync_identifier_cache() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.is_primary AND NEW.effective_to IS NULL THEN
        IF NEW.id_type = 'ISIN'  THEN UPDATE orm.security SET isin  = NEW.id_value WHERE id = NEW.security_id;
        ELSIF NEW.id_type = 'CUSIP' THEN UPDATE orm.security SET cusip = NEW.id_value WHERE id = NEW.security_id;
        ELSIF NEW.id_type = 'TICKER' THEN UPDATE orm.security SET ticker = NEW.id_value WHERE id = NEW.security_id;
        END IF;
    END IF;
    RETURN NEW;
END $$;


